'use client';

import { useState } from 'react';
import type { TaskStatus, Priority } from '@/lib/types';

interface NewTaskFormProps {
  onClose: () => void;
  onSuccess: () => void;
}

export function NewTaskForm({ onClose, onSuccess }: NewTaskFormProps) {
  const [title, setTitle] = useState('');
  const [status, setStatus] = useState<TaskStatus>('todo');
  const [priority, setPriority] = useState<Priority>('medium');
  const [project, setProject] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setSubmitting(true);
    setError(null);
    try {
      const res = await fetch('/api/tasks', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          title: title.trim(),
          source: 'notion',
          status,
          priority,
          project: project.trim() || undefined,
          dueDate: dueDate || undefined,
        }),
      });
      if (!res.ok) {
        const data = (await res.json()) as { error?: string };
        throw new Error(data.error ?? String(res.status));
      }
      onSuccess();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create task');
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50"
      onClick={onClose}
    >
      <div
        className="bg-[var(--bg-card)] border border-[var(--border)] rounded-xl p-6 w-full max-w-md mx-4 shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-sm font-semibold">New Task</h2>
          <button
            type="button"
            onClick={onClose}
            className="text-[var(--text-3)] hover:text-[var(--text-1)] text-sm leading-none"
            aria-label="Close"
          >
            ✕
          </button>
        </div>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs text-[var(--text-3)] mb-1">
              Title <span className="text-red-400">*</span>
            </label>
            <input
              type="text"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              required
              autoFocus
              className="w-full px-3 py-2 text-sm rounded-lg border border-[var(--border)] bg-[var(--bg-hover)] focus:outline-none focus:ring-1 focus:ring-blue-500"
              placeholder="Task title"
            />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs text-[var(--text-3)] mb-1">Status</label>
              <select
                value={status}
                onChange={(e) => setStatus(e.target.value as TaskStatus)}
                className="w-full px-3 py-2 text-sm rounded-lg border border-[var(--border)] bg-[var(--bg-hover)] focus:outline-none focus:ring-1 focus:ring-blue-500"
              >
                <option value="todo">To Do</option>
                <option value="in_progress">In Progress</option>
                <option value="done">Done</option>
                <option value="blocked">Blocked</option>
              </select>
            </div>
            <div>
              <label className="block text-xs text-[var(--text-3)] mb-1">Priority</label>
              <select
                value={priority}
                onChange={(e) => setPriority(e.target.value as Priority)}
                className="w-full px-3 py-2 text-sm rounded-lg border border-[var(--border)] bg-[var(--bg-hover)] focus:outline-none focus:ring-1 focus:ring-blue-500"
              >
                <option value="high">High</option>
                <option value="medium">Medium</option>
                <option value="low">Low</option>
                <option value="none">None</option>
              </select>
            </div>
          </div>
          <div>
            <label className="block text-xs text-[var(--text-3)] mb-1">Project</label>
            <input
              type="text"
              value={project}
              onChange={(e) => setProject(e.target.value)}
              className="w-full px-3 py-2 text-sm rounded-lg border border-[var(--border)] bg-[var(--bg-hover)] focus:outline-none focus:ring-1 focus:ring-blue-500"
              placeholder="Project name"
            />
          </div>
          <div>
            <label className="block text-xs text-[var(--text-3)] mb-1">Due Date</label>
            <input
              type="date"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
              className="w-full px-3 py-2 text-sm rounded-lg border border-[var(--border)] bg-[var(--bg-hover)] focus:outline-none focus:ring-1 focus:ring-blue-500"
            />
          </div>
          {error && <p className="text-xs text-red-400">{error}</p>}
          <div className="flex gap-3 pt-1">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-2 text-sm rounded-lg border border-[var(--border)] hover:bg-[var(--bg-hover)] transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting || !title.trim()}
              className="flex-1 px-4 py-2 text-sm rounded-lg bg-blue-500 text-white hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {submitting ? 'Creating…' : 'Create'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

"use client";

import type { Task, TaskStatus, Priority } from "@/lib/types";

const statusColors: Record<string, string> = {
  todo: "bg-purple-500/10 text-purple-400",
  in_progress: "bg-amber-500/10 text-amber-400",
  done: "bg-emerald-500/10 text-emerald-400",
  blocked: "bg-red-500/10 text-red-400",
};

const priorityDot: Record<string, string> = {
  high: "bg-red-400",
  medium: "bg-amber-400",
  low: "bg-blue-400",
  none: "bg-gray-500",
};

const sourceIcon: Record<string, string> = {
  notion: "N",
  github: "GH",
};

function daysUntil(dateStr?: string): number | null {
  if (!dateStr) return null;
  const diff = new Date(dateStr).getTime() - Date.now();
  return Math.ceil(diff / (1000 * 60 * 60 * 24));
}

interface AssignmentsListProps {
  tasks: Task[];
  onNew?: () => void;
  onStatusChange: (id: string, status: TaskStatus) => void;
  onPriorityChange: (id: string, priority: Priority) => void;
  onDelete: (id: string) => void;
}

export function AssignmentsList({
  tasks,
  onNew,
  onStatusChange,
  onPriorityChange,
  onDelete,
}: AssignmentsListProps) {
  const sorted = [...tasks].sort((a, b) => {
    const prio = { high: 0, medium: 1, low: 2, none: 3 };
    const statusOrder = { in_progress: 0, todo: 1, blocked: 2, done: 3 };
    const diff = (statusOrder[a.status] ?? 3) - (statusOrder[b.status] ?? 3);
    if (diff !== 0) return diff;
    return (prio[a.priority] ?? 3) - (prio[b.priority] ?? 3);
  });

  return (
    <div className="bg-[var(--bg-card)] border border-[var(--border)] rounded-xl overflow-hidden">
      <div className="px-4 py-3 border-b border-[var(--border)] flex items-center justify-between gap-2">
        <div>
          <h2 className="text-sm font-semibold">My Assignments</h2>
          <p className="text-xs text-[var(--text-3)]">
            From Notion + GitHub — sorted by status &amp; priority
          </p>
        </div>
        {onNew && (
          <button
            type="button"
            onClick={onNew}
            className="flex-shrink-0 text-xs px-2.5 py-1 rounded-lg bg-blue-500 text-white hover:bg-blue-600 transition-colors"
          >
            + New
          </button>
        )}
      </div>
      <div className="divide-y divide-[var(--border)] max-h-[400px] overflow-y-auto">
        {sorted.map((task) => {
          const days = daysUntil(task.dueDate);
          const isOverdue = days !== null && days < 0;
          const isDueSoon = days !== null && days >= 0 && days <= 3;

          return (
            <div
              key={task.id}
              className="px-4 py-3 hover:bg-[var(--bg-hover)] transition-colors flex items-start gap-3 group"
            >
              <div
                className={`w-2 h-2 rounded-full mt-1.5 flex-shrink-0 ${priorityDot[task.priority]}`}
              />
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-sm font-medium truncate">{task.title}</span>
                  {task.sourceUrl ? (
                    <a
                      href={task.sourceUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-[0.6rem] px-1.5 py-0.5 rounded bg-[var(--bg-hover)] text-[var(--text-3)] hover:text-[var(--text-2)] flex-shrink-0"
                    >
                      {sourceIcon[task.source]}
                    </a>
                  ) : (
                    <span className="text-[0.6rem] px-1.5 py-0.5 rounded bg-[var(--bg-hover)] text-[var(--text-3)] flex-shrink-0">
                      {sourceIcon[task.source]}
                    </span>
                  )}
                </div>
                <div className="flex items-center gap-2 flex-wrap">
                  {task.project && (
                    <span className="text-[0.65rem] text-[var(--text-3)]">{task.project}</span>
                  )}
                  <select
                    value={task.status}
                    onChange={(e) => onStatusChange(task.id, e.target.value as TaskStatus)}
                    aria-label="Status"
                    className={`text-[0.6rem] px-1.5 py-0.5 rounded font-medium border-0 cursor-pointer appearance-none ${statusColors[task.status]}`}
                  >
                    <option value="todo">to do</option>
                    <option value="in_progress">in progress</option>
                    <option value="done">done</option>
                    <option value="blocked">blocked</option>
                  </select>
                  <select
                    value={task.priority}
                    onChange={(e) => onPriorityChange(task.id, e.target.value as Priority)}
                    aria-label="Priority"
                    className="text-[0.6rem] px-1.5 py-0.5 rounded bg-[var(--bg-hover)] text-[var(--text-3)] border-0 cursor-pointer appearance-none"
                  >
                    <option value="high">↑ high</option>
                    <option value="medium">→ medium</option>
                    <option value="low">↓ low</option>
                    <option value="none">– none</option>
                  </select>
                  {task.tags?.map((tag) => (
                    <span
                      key={tag}
                      className="text-[0.6rem] px-1.5 py-0.5 rounded bg-[var(--bg-hover)] text-[var(--text-3)]"
                    >
                      {tag}
                    </span>
                  ))}
                  {isOverdue && (
                    <span className="text-[0.6rem] px-1.5 py-0.5 rounded bg-red-500/10 text-red-400 font-medium">
                      {Math.abs(days!)}d overdue
                    </span>
                  )}
                  {isDueSoon && (
                    <span className="text-[0.6rem] px-1.5 py-0.5 rounded bg-amber-500/10 text-amber-400 font-medium">
                      due in {days}d
                    </span>
                  )}
                </div>
              </div>
              <button
                type="button"
                onClick={() => onDelete(task.id)}
                aria-label="Delete task"
                className="flex-shrink-0 mt-0.5 w-5 h-5 flex items-center justify-center text-[0.65rem] text-[var(--text-3)] hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity rounded"
              >
                ✕
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { render, screen } from "@testing-library/react";
import { describe, it, expect, vi } from "vitest";
import { AssignmentsList } from "./AssignmentsList";
import type { Task } from "@/lib/types";

const noop = vi.fn();

const makeTasks = (overrides: Partial<Task>[] = []): Task[] => [
  {
    id: "t1",
    title: "High priority in-progress task",
    source: "notion",
    status: "in_progress",
    priority: "high",
    ...overrides[0],
  },
  {
    id: "t2",
    title: "Medium priority todo task",
    source: "github",
    sourceUrl: "https://github.com/example/repo/issues/1",
    status: "todo",
    priority: "medium",
    project: "TestProject",
    tags: ["feature"],
    ...overrides[1],
  },
  {
    id: "t3",
    title: "Done task",
    source: "notion",
    status: "done",
    priority: "low",
    ...overrides[2],
  },
];

const defaultProps = {
  onStatusChange: noop,
  onPriorityChange: noop,
  onDelete: noop,
};

describe("AssignmentsList", () => {
  it("renders all tasks", () => {
    render(<AssignmentsList tasks={makeTasks()} {...defaultProps} />);
    expect(screen.getByText("High priority in-progress task")).toBeInTheDocument();
    expect(screen.getByText("Medium priority todo task")).toBeInTheDocument();
    expect(screen.getByText("Done task")).toBeInTheDocument();
  });

  it("sorts by status then priority (in_progress first, done last)", () => {
    const { container } = render(<AssignmentsList tasks={makeTasks()} {...defaultProps} />);
    const items = container.querySelectorAll(".text-sm.font-medium");
    expect(items[0]).toHaveTextContent("High priority in-progress task");
    expect(items[2]).toHaveTextContent("Done task");
  });

  it("displays source badge for Notion tasks", () => {
    render(<AssignmentsList tasks={makeTasks()} {...defaultProps} />);
    const badges = screen.getAllByText("N");
    expect(badges.length).toBeGreaterThan(0);
  });

  it("renders GitHub source as a link when sourceUrl exists", () => {
    render(<AssignmentsList tasks={makeTasks()} {...defaultProps} />);
    const ghLink = screen.getByText("GH").closest("a");
    expect(ghLink).toHaveAttribute("href", "https://github.com/example/repo/issues/1");
    expect(ghLink).toHaveAttribute("target", "_blank");
  });

  it("displays project name when present", () => {
    render(<AssignmentsList tasks={makeTasks()} {...defaultProps} />);
    expect(screen.getByText("TestProject")).toBeInTheDocument();
  });

  it("displays tags", () => {
    render(<AssignmentsList tasks={makeTasks()} {...defaultProps} />);
    expect(screen.getByText("feature")).toBeInTheDocument();
  });

  it("shows overdue badge for past-due tasks", () => {
    const tasks = makeTasks([{ dueDate: "2020-01-01" }]);
    render(<AssignmentsList tasks={tasks} {...defaultProps} />);
    expect(screen.getByText(/overdue/)).toBeInTheDocument();
  });

  it("shows due-soon badge for tasks due within 3 days", () => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    const tasks = makeTasks([{ dueDate: tomorrow.toISOString().split("T")[0] }]);
    render(<AssignmentsList tasks={tasks} {...defaultProps} />);
    expect(screen.getByText(/due in/)).toBeInTheDocument();
  });

  it("renders empty list without crashing", () => {
    render(<AssignmentsList tasks={[]} {...defaultProps} />);
    expect(screen.getByText("My Assignments")).toBeInTheDocument();
  });

  it("renders a status select for each task", () => {
    render(<AssignmentsList tasks={makeTasks()} {...defaultProps} />);
    const selects = screen.getAllByRole("combobox", { name: "Status" });
    expect(selects).toHaveLength(3);
  });

  it("renders a delete button for each task", () => {
    render(<AssignmentsList tasks={makeTasks()} {...defaultProps} />);
    const delButtons = screen.getAllByRole("button", { name: "Delete task" });
    expect(delButtons).toHaveLength(3);
  });

  it("renders a New button when onNew is provided", () => {
    const onNew = vi.fn();
    render(<AssignmentsList tasks={[]} {...defaultProps} onNew={onNew} />);
    expect(screen.getByRole("button", { name: /New/i })).toBeInTheDocument();
  });
});

'use client';

import { useState, useMemo, useCallback } from 'react';
import { useTasks } from '@/hooks/useTasks';
import { detectGaps } from '@/lib/gap-detection';
import { mockData } from '@/lib/mock-data';
import { StatCards } from './StatCards';
import { AssignmentsList } from './AssignmentsList';
import { ActivityFeed } from './ActivityFeed';
import { GapAnalysis } from './GapAnalysis';
import { RhythmChart } from './RhythmChart';
import { NewTaskForm } from './NewTaskForm';
import type { TaskStatus, Priority } from '@/lib/types';

export function Dashboard() {
  const { tasks, loading, error, refresh } = useTasks();
  const { activity, rhythm } = mockData;
  const [showNewTaskForm, setShowNewTaskForm] = useState(false);

  const stats = useMemo(() => {
    const totalTasks = tasks.length;
    const inProgress = tasks.filter((t) => t.status === 'in_progress').length;
    const now = new Date();
    const overdue = tasks.filter(
      (t) => t.dueDate && new Date(t.dueDate) < now && t.status !== 'done'
    ).length;
    const done = tasks.filter((t) => t.status === 'done').length;
    const finishRate = totalTasks > 0 ? done / totalTasks : 0;
    const activeRepos = new Set(
      tasks.map((t) => t.project).filter(Boolean)
    ).size;
    return { totalTasks, inProgress, overdue, finishRate, activeRepos };
  }, [tasks]);

  const gaps = useMemo(() => detectGaps(tasks, activity), [tasks, activity]);

  const handleStatusChange = useCallback(
    (id: string, status: TaskStatus) => {
      fetch(`/api/tasks/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status }),
      }).then(() => refresh());
    },
    [refresh],
  );

  const handlePriorityChange = useCallback(
    (id: string, priority: Priority) => {
      fetch(`/api/tasks/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ priority }),
      }).then(() => refresh());
    },
    [refresh],
  );

  const handleDelete = useCallback(
    (id: string) => {
      fetch(`/api/tasks/${id}`, { method: 'DELETE' }).then(() => refresh());
    },
    [refresh],
  );

  if (loading) {
    return (
      <div className="space-y-6 animate-pulse">
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4">
          {Array.from({ length: 5 }).map((_, i) => (
            <div key={i} className="h-24 rounded-xl bg-gray-100 dark:bg-gray-800" />
          ))}
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {Array.from({ length: 4 }).map((_, i) => (
            <div key={i} className="h-64 rounded-xl bg-gray-100 dark:bg-gray-800" />
          ))}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="rounded-xl border border-red-200 bg-red-50 p-6 text-red-700 dark:border-red-800 dark:bg-red-950 dark:text-red-400">
        <p className="font-medium">Failed to load tasks</p>
        <p className="mt-1 text-sm opacity-80">{error}</p>
      </div>
    );
  }

  return (
    <>
      {showNewTaskForm && (
        <NewTaskForm
          onClose={() => setShowNewTaskForm(false)}
          onSuccess={() => {
            setShowNewTaskForm(false);
            refresh();
          }}
        />
      )}
      <div className="space-y-6">
        <StatCards
          totalTasks={stats.totalTasks}
          inProgress={stats.inProgress}
          overdue={stats.overdue}
          finishRate={stats.finishRate}
          activeRepos={stats.activeRepos}
        />
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <AssignmentsList
            tasks={tasks}
            onNew={() => setShowNewTaskForm(true)}
            onStatusChange={handleStatusChange}
            onPriorityChange={handlePriorityChange}
            onDelete={handleDelete}
          />
          <ActivityFeed events={activity} />
          <GapAnalysis gaps={gaps} />
          <RhythmChart data={rhythm} />
        </div>
      </div>
    </>
  );
}
